import sys

def nthCharacter(S: str, R: int, N: int) -> str:
    current = S
    for _ in range(R):
        new_chars = []
        for char in current:
            if char == '0':
                new_chars.append('0')
                new_chars.append('1')
            else:
                new_chars.append('1')
                new_chars.append('0')
        current = "".join(new_chars)
    return current[N]

def main():
    lines = sys.stdin.read().split()
    if not lines:
        return
    S = lines[0]
    R = int(lines[1])
    N = int(lines[2])
    result = nthCharacter(S, R, N)
    print(result)

if __name__ == "__main__":
    main()
